import json

with open('system-spec/spec-state.json', encoding='utf-8') as f:
    data = json.load(f)

cats = [c['id'] for c in data.get('categories', [])]
matrix = data.get('matrix', {})
qa_log = data.get('qa_log', [])
qa_ids = {e['id'] for e in qa_log}
appr_log = data.get('approval_log', [])
appr_ids = {e['id'] for e in appr_log}
ref_ids = qa_ids | appr_ids

CANONICAL = ['web','mobile','tablet','desktop-windows','desktop-linux','desktop-macos']

# Check for duplicate approval_log ids
seen = {}
for e in appr_log:
    eid = e.get('id', '')
    seen[eid] = seen.get(eid, 0) + 1
dups = {k: v for k, v in seen.items() if v > 1}
if dups:
    print('DUPLICATE APPR IDS: ' + str(dups))
else:
    print('All approval_log ids unique')

# Check cross-log id collision
collision = qa_ids & appr_ids
if collision:
    print('CROSS-LOG ID COLLISION: ' + str(sorted(collision)))
else:
    print('No cross-log id collision between qa_log and approval_log')

print()
print('=== DETAILED CELL CHECK (all 60 cells) ===')
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL:
        cell = row.get(pf)
        if cell is None:
            print('CELL MISSING: ' + cat + ' x ' + pf)
            continue
        st = cell.get('state')
        if st == '確定':
            qa_ref = cell.get('qa_ref', '')
            serves = cell.get('serves_goals', [])
            dangling = qa_ref not in ref_ids if qa_ref else False
            no_goals = not serves
            issues = []
            if not qa_ref:
                issues.append('qa_ref empty')
            elif dangling:
                issues.append('qa_ref dangling: ' + qa_ref)
            if no_goals:
                issues.append('serves_goals empty')
            if issues:
                print('ISSUE ' + cat + ' x ' + pf + ': ' + ', '.join(issues))
            # else good
        elif st == '対象外':
            reason = cell.get('reason', '')
            appr_ref = cell.get('approval_ref', '')
            if not reason:
                if appr_ref not in appr_ids:
                    print('EXCLUDED NO REASON: ' + cat + ' x ' + pf)
                else:
                    pass  # approval_ref covers it
            else:
                # Check for placeholder
                stripped = reason.strip()
                placeholders = ['-', 'n/a', 'N/A', '対象外', '']
                if stripped in placeholders:
                    print('PLACEHOLDER REASON: ' + cat + ' x ' + pf + ' reason=' + repr(stripped))
        elif st == '未収集':
            print('UNCOLLECTED: ' + cat + ' x ' + pf)
        else:
            print('INVALID STATE: ' + cat + ' x ' + pf + ' state=' + repr(st))

print()
print('Done. checking goal traceability...')

# Check serves_goals ref real goals
rf = data.get('requirements_foundation', {})
goals = rf.get('goals', [])
goal_ids = {g['id'] for g in goals} if goals else set()
print('Goal IDs in requirements_foundation: ' + str(sorted(goal_ids)))

bad_goal_refs = []
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL:
        cell = row.get(pf)
        if cell and cell.get('state') == '確定':
            for gid in cell.get('serves_goals', []):
                if gid not in goal_ids:
                    bad_goal_refs.append(cat + ' x ' + pf + ': goal ' + gid + ' not in requirements_foundation.goals')
if bad_goal_refs:
    print('BAD GOAL REFS: ')
    for b in bad_goal_refs:
        print('  ' + b)
else:
    print('All serves_goals refs resolve to real goals')

PYEOF

